package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceBusinessExceptionModels.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Explicit noncash receivable exceptions and configured tax obligations; neither pretends external execution. */
@Service @Transactional
public class FinanceBusinessExceptionService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext db;private final AccessPolicy access;private final AuditWriter audit;private final FinanceAccountingService accounting;
 public FinanceBusinessExceptionService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext db,AccessPolicy access,AuditWriter audit,FinanceAccountingService accounting){this.jdbc=jdbc;this.db=db;this.access=access;this.audit=audit;this.accounting=accounting;}
 public Map<String,Object> adjustments(){var p=prepare("finance.read","finance.review");var values=jdbc.queryForList("select a.* from fb_receivable_adjustment a where a.tenant_id=:tenant and "+scope("a")+" order by a.created_at desc,a.id limit 201",base(p));return Map.of("items",values.stream().limit(200).map(FinanceV2Support::output).toList(),"complete",values.size()<=200);}
 public Map<String,Object> recoveries(){var p=prepare("finance.read","finance.review");var values=jdbc.queryForList("select r.*,a.kind original_kind,a.amount original_loss_amount from fb_receivable_recovery r join fb_receivable_adjustment a on a.tenant_id=r.tenant_id and a.id=r.adjustment_id where r.tenant_id=:tenant and "+scope("r")+" order by r.created_at desc,r.id limit 201",base(p));return Map.of("items",values.stream().limit(200).map(FinanceV2Support::output).toList(),"complete",values.size()<=200);}
 public Map<String,Object> recovery(Recovery in){
  var p=prepare("finance.read","finance.review");access.requirePermission("finance.submit");lock(p,"request:"+in.requestId());
  var prior=jdbc.queryForList("select * from fb_receivable_recovery where tenant_id=:tenant and id=:id",base(p).addValue("id",in.requestId()));
  if(!prior.isEmpty()){access.requireOrgScope(id(prior.getFirst().get("hotel_id")));if(!p.actorId().equals(prior.getFirst().get("created_by"))||!FinanceService.hash(json(in)).equals(prior.getFirst().get("request_hash")))throw conflict("恢复编号已用于其他内容");return output(prior.getFirst());}
  var loss=load(p,"fb_receivable_adjustment",in.adjustmentId(),true);if(!"CONFIRMED".equals(loss.get("status")))throw conflict("只能恢复真实已独立确认的原坏账/渠道差额，不能恢复待审核或已拒绝记录");
  var row=latestAdjustmentEntry(p,loss);sourceVersion(row,in.expectedSourceVersion());var cfg=config(p,id(row.get("hotel_id")));independent(p,cfg,in.reviewerId());
  if(in.reviewerId().equals(loss.get("reviewed_by")))throw conflict("恢复须由不同于原损失确认人的独立财务/总监审核，不能自行撤回原批准结论");
  validateRecovery(p,loss,row,in.amount(),in.accountingDate(),in.proofAttachmentId());var snapshot=new LinkedHashMap<String,Object>();snapshot.put("originalLoss",output(loss));snapshot.put("currentEntry",output(row));snapshot.put("unrecoveredBefore",remainingRecovery(p,loss));snapshot.put("outstandingBefore",outstanding(p,row));snapshot.put("receiptState",output(receiptState(p,row)));snapshot.put("meaning","原应收误核销恢复，不是再次确认收入，不是执行收款或删除原损失");
  jdbc.update("insert into fb_receivable_recovery(id,tenant_id,adjustment_id,entry_id,hotel_id,company_id,amount,business_date,accounting_on,source_version,source_hash,request_hash,proof_attachment_id,reason,snapshot,created_by,reviewer_id) values(:id,:tenant,:loss,:entry,:hotel,:company,:amount,:business,:day,:version,:hash,:requestHash,:proof,:reason,cast(:snapshot as jsonb),:actor,:reviewer)",base(p).addValue("id",in.requestId()).addValue("loss",in.adjustmentId()).addValue("entry",row.get("id")).addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")).addValue("amount",money(in.amount())).addValue("business",loss.get("business_date")).addValue("day",in.accountingDate()).addValue("version",in.expectedSourceVersion()).addValue("hash",hash(row)).addValue("requestHash",FinanceService.hash(json(in))).addValue("proof",in.proofAttachmentId()).addValue("reason",in.reason()).addValue("snapshot",json(snapshot)).addValue("reviewer",in.reviewerId()));
  notifyReview(p,"FINANCE_AR_RECOVERY",in.requestId(),in.reviewerId());audit.record("FINANCE_RECEIVABLE_RECOVERY_REQUESTED","FINANCE_RECEIVABLE_RECOVERY",in.requestId(),"{}");return output(load(p,"fb_receivable_recovery",in.requestId(),false));
 }
 public Map<String,Object> reviewRecovery(UUID recovery,Review in){
  var p=prepare("finance.review");var r=load(p,"fb_receivable_recovery",recovery,true);reviewer(p,r);if(!"REVIEW".equals(r.get("status"))){if(((Number)r.get("version")).intValue()==in.expectedVersion()+1&&p.actorId().equals(r.get("reviewed_by"))&&Objects.equals(r.get("review_note"),in.note())&&(in.approve()?"CONFIRMED":"REJECTED").equals(r.get("status")))return output(r);throw conflict("恢复已独立处理，不能改变冻结结论");}version(r,in.expectedVersion());
  var loss=load(p,"fb_receivable_adjustment",id(r.get("adjustment_id")),true);
  if(in.approve()){
   var row=latestAdjustmentEntry(p,loss);configured(config(p,id(r.get("hotel_id"))),p.actorId());if(p.actorId().equals(loss.get("reviewed_by")))throw conflict("不能由原损失确认人自行恢复原批准结论");sourceVersion(row,((Number)r.get("source_version")).intValue());var snapshot=map(r.get("snapshot"));
   // JSONB canonicalizes object key order. Compare the same actual dependency structure, not serialized order.
   if(!row.get("id").equals(r.get("entry_id"))||!r.get("source_hash").equals(hash(row))||remainingRecovery(p,loss).compareTo(amount(snapshot.get("unrecoveredBefore")))!=0||outstanding(p,row).compareTo(amount(snapshot.get("outstandingBefore")))!=0||!JSON.valueToTree(output(receiptState(p,row))).equals(JSON.valueToTree(snapshot.get("receiptState"))))throw conflict("原损失已恢复、来源版本或实际收款/消费核销已改变，请拒绝旧快照并重新核对");
   validateRecovery(p,loss,row,amount(r.get("amount")),LocalDate.parse(r.get("accounting_on").toString()),id(r.get("proof_attachment_id")));
  }
  update(p,"fb_receivable_recovery",recovery,in.approve()?"CONFIRMED":"REJECTED",in.note());
  if(in.approve()){var metadata=new LinkedHashMap<String,String>();metadata.put("businessTable","fb_receivable_recovery");metadata.put("businessId",recovery.toString());metadata.put("companyId",r.get("company_id").toString());metadata.put("originalAdjustmentId",loss.get("id").toString());metadata.put("entryId",r.get("entry_id").toString());metadata.put("proofAttachmentId",r.get("proof_attachment_id").toString());metadata.put("meaning","NON_CASH_RESTORE_ORIGINAL_RECEIVABLE_NOT_NEW_REVENUE");accounting.recordSourceEvent(id(r.get("hotel_id")),"FB_RECEIVABLE_RECOVERY",recovery,loss.get("kind")+"_RECOVERY",LocalDate.parse(r.get("business_date").toString()),LocalDate.parse(r.get("accounting_on").toString()),amount(r.get("amount")),"独立恢复原应收误核销（不再次确认收入）",metadata);}
  audit.record(in.approve()?"FINANCE_RECEIVABLE_RECOVERY_CONFIRMED":"FINANCE_RECEIVABLE_RECOVERY_REJECTED","FINANCE_RECEIVABLE_RECOVERY",recovery,json(Map.of("note",in.note())));return output(load(p,"fb_receivable_recovery",recovery,false));
 }
 private BigDecimal remainingRecovery(TenantPrincipal p,Map<String,Object> loss){return amount(loss.get("amount")).subtract(jdbc.queryForObject("select coalesce(sum(amount),0) from fb_receivable_recovery where tenant_id=:tenant and adjustment_id=:id and status='CONFIRMED' and accounting_on<=:asof",base(p).addValue("id",loss.get("id")).addValue("asof",today()),BigDecimal.class));}
 private Map<String,Object> latestAdjustmentEntry(TenantPrincipal p,Map<String,Object> loss){var ids=jdbc.queryForList("select e.id from fb_revenue_entry original join fb_revenue_batch ob on ob.tenant_id=original.tenant_id and ob.id=original.batch_id join fb_revenue_entry e on e.tenant_id=original.tenant_id and e.hotel_id=original.hotel_id and e.company_id=original.company_id and e.external_id=original.external_id and e.customer=original.customer and e.active join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id and b.source=ob.source and b.channel=ob.channel and b.business_date=ob.business_date where original.tenant_id=:tenant and original.id=:id",base(p).addValue("id",loss.get("entry_id")));if(ids.size()!=1)throw conflict("原损失的当前真实应收来源不唯一或已不可用，请先独立核对来源");return entry(p,id(ids.getFirst().get("id")),true);}
 private Map<String,Object> receiptState(TenantPrincipal p,Map<String,Object> row){return jdbc.queryForMap("select coalesce(sum(fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asof)) filter(where m.kind='RECEIPT'),0) received,coalesce(sum(fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asof)) filter(where m.kind='REFUND'),0) refunded,fb_revenue_redeemed_into(:tenant,:entry,:asof) redeemed from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where m.tenant_id=:tenant and e.hotel_id=:hotel and e.external_id=:external and b.source=:source and b.channel=:channel and b.business_date=:business and m.occurred_on<=:asof",base(p).addValue("entry",row.get("id")).addValue("hotel",row.get("hotel_id")).addValue("external",row.get("external_id")).addValue("source",row.get("source")).addValue("channel",row.get("channel")).addValue("business",row.get("business_date")).addValue("asof",today()));}
 private void validateRecovery(TenantPrincipal p,Map<String,Object> loss,Map<String,Object> row,BigDecimal value,LocalDate day,UUID proof){
  money(value);if(value.signum()<=0||value.compareTo(remainingRecovery(p,loss))>0)throw conflict("恢复不能超过同一原损失尚未恢复的金额，不能跨来源重复恢复");if(outstanding(p,row).add(value).signum()<0)throw conflict("实际收款/消费核销与原损失重叠，部分恢复后仍超清，请先核对依赖再办理正确恢复额");
  if(day.isBefore(LocalDate.parse(loss.get("accounting_on").toString()))||day.isAfter(today()))throw bad("恢复记账日须不早于原损失记账日且不晚于今天，原业务日期保持不变");
  var cfg=config(p,id(row.get("hotel_id")));if(!Objects.equals(cfg.get("company_id"),loss.get("company_id"))||!Objects.equals(loss.get("company_id"),row.get("company_id")))throw conflict("原损失、当前真实应收与配置法人不同，请先独立核对主体");
  for(var book:jdbc.queryForList("select id from fa_book where tenant_id=:tenant and hotel_id=:hotel and enabled order by id",base(p).addValue("hotel",row.get("hotel_id"))))jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,0))",Map.of("key",p.tenantId()+":book:"+book.get("id")));
  if(jdbc.queryForObject("select count(*) from fa_period x join fa_book b on b.tenant_id=x.tenant_id and b.id=x.book_id where b.tenant_id=:tenant and b.hotel_id=:hotel and b.enabled and x.month=:month and x.status='CLOSED'",base(p).addValue("hotel",row.get("hotel_id")).addValue("month",YearMonth.from(day).atDay(1)),Integer.class)>0)throw conflict("恢复记账期间已锁定，请选择当前开放期，不得回写旧期间");
  if(jdbc.queryForObject("select count(*) from fb_attachment a where a.tenant_id=:tenant and a.id=:proof and a.hotel_id=:hotel and a.domain='REVENUE' and (a.resource_id=:batch or a.resource_id=(select batch_id from fb_revenue_entry where tenant_id=:tenant and id=:original))",base(p).addValue("proof",proof).addValue("hotel",row.get("hotel_id")).addValue("batch",row.get("batch_id")).addValue("original",loss.get("entry_id")),Integer.class)!=1)throw conflict("请先在原来源或当前修订批次归档真实误核销恢复依据，不能借用其他来源原件");
 }
 public Map<String,Object> adjustment(Adjustment in){var p=prepare("finance.read","finance.review");access.requirePermission("finance.submit");lock(p,"request:"+in.requestId());var old=jdbc.queryForList("select * from fb_receivable_adjustment where tenant_id=:tenant and id=:id",base(p).addValue("id",in.requestId()));if(!old.isEmpty()){access.requireOrgScope(id(old.getFirst().get("hotel_id")));if(!p.actorId().equals(old.getFirst().get("created_by"))||!FinanceService.hash(json(in)).equals(old.getFirst().get("request_hash")))throw conflict("调整编号已用于其他内容");return output(old.getFirst());}var row=entry(p,in.entryId(),true);sourceVersion(row,in.expectedSourceVersion());var cfg=config(p,id(row.get("hotel_id")));if(!Objects.equals(cfg.get("company_id"),row.get("company_id")))throw conflict("原应收冻结法人已不同于当前配置，须先核对主体再办理");independent(p,cfg,in.reviewerId());validateAdjustment(p,row,in.amount(),in.accountingDate(),in.proofAttachmentId());var snapshot=new LinkedHashMap<String,Object>();snapshot.put("entry",output(row));snapshot.put("outstandingBefore",outstanding(p,row));snapshot.put("meaning","只核销经独立确认的未收差额，不改原收入、发票或实收，不自动作为税前扣除");var b=base(p).addValue("id",in.requestId()).addValue("entry",in.entryId()).addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")).addValue("kind",in.kind()).addValue("amount",money(in.amount())).addValue("business",row.get("business_date")).addValue("day",in.accountingDate()).addValue("sourceVersion",in.expectedSourceVersion()).addValue("hash",hash(row)).addValue("requestHash",FinanceService.hash(json(in))).addValue("proof",in.proofAttachmentId()).addValue("reason",in.reason()).addValue("snapshot",json(snapshot)).addValue("reviewer",in.reviewerId());jdbc.update("insert into fb_receivable_adjustment(id,tenant_id,entry_id,hotel_id,company_id,kind,amount,business_date,accounting_on,source_version,source_hash,request_hash,proof_attachment_id,reason,snapshot,created_by,reviewer_id) values(:id,:tenant,:entry,:hotel,:company,:kind,:amount,:business,:day,:sourceVersion,:hash,:requestHash,:proof,:reason,cast(:snapshot as jsonb),:actor,:reviewer)",b);notifyReview(p,"FINANCE_AR_ADJUSTMENT",in.requestId(),in.reviewerId());audit.record("FINANCE_RECEIVABLE_ADJUSTMENT_REQUESTED","FINANCE_RECEIVABLE_ADJUSTMENT",in.requestId(),"{}");return output(load(p,"fb_receivable_adjustment",in.requestId(),false));}
 public Map<String,Object> reviewAdjustment(UUID adjustment,Review in){var p=prepare("finance.review");var a=load(p,"fb_receivable_adjustment",adjustment,true);reviewer(p,a);if(!"REVIEW".equals(a.get("status")))throw conflict("调整已处理，不能改变冻结结论");version(a,in.expectedVersion());if(in.approve()){var row=entry(p,id(a.get("entry_id")),true);var cfg=config(p,id(a.get("hotel_id")));configured(cfg,p.actorId());if(!Objects.equals(cfg.get("company_id"),a.get("company_id")))throw conflict("原应收冻结法人已不同于当前配置，请先独立核对");sourceVersion(row,((Number)a.get("source_version")).intValue());if(!a.get("source_hash").equals(hash(row))||outstanding(p,row).compareTo(amount(map(a.get("snapshot")).get("outstandingBefore")))!=0)throw conflict("原来源版本或未清金额已改变，请拒绝旧快照并重新申请");validateAdjustment(p,row,amount(a.get("amount")),LocalDate.parse(a.get("accounting_on").toString()),id(a.get("proof_attachment_id")));}update(p,"fb_receivable_adjustment",adjustment,in.approve()?"CONFIRMED":"REJECTED",in.note());if(in.approve()){var metadata=new LinkedHashMap<String,String>();metadata.put("businessTable","fb_receivable_adjustment");metadata.put("businessId",adjustment.toString());metadata.put("companyId",a.get("company_id").toString());metadata.put("entryId",a.get("entry_id").toString());metadata.put("proofAttachmentId",a.get("proof_attachment_id").toString());metadata.put("meaning","NON_CASH_RECEIVABLE_WRITEOFF_NOT_REVENUE_REWRITE");accounting.recordSourceEvent(id(a.get("hotel_id")),"FB_RECEIVABLE_ADJUSTMENT",adjustment,a.get("kind").toString(),LocalDate.parse(a.get("business_date").toString()),LocalDate.parse(a.get("accounting_on").toString()),amount(a.get("amount")),"独立确认未收差额核销",metadata);}audit.record(in.approve()?"FINANCE_RECEIVABLE_ADJUSTMENT_CONFIRMED":"FINANCE_RECEIVABLE_ADJUSTMENT_REJECTED","FINANCE_RECEIVABLE_ADJUSTMENT",adjustment,json(Map.of("note",in.note())));return output(load(p,"fb_receivable_adjustment",adjustment,false));}
 public Map<String,Object> calendar(){var p=prepare("finance.tax");var values=jdbc.queryForList("select c.*,l.return_id,r.declared_amount from fb_tax_calendar c left join fb_tax_calendar_link l on l.tenant_id=c.tenant_id and l.calendar_id=c.id left join fb_tax_return r on r.tenant_id=l.tenant_id and r.id=l.return_id where c.tenant_id=:tenant and "+scope("c")+" order by c.due_on,c.id limit 201",base(p));var result=new ArrayList<Map<String,Object>>();for(var row:values.stream().limit(200).toList()){if(row.get("return_id")!=null)FinanceTaxScope.forReturn(jdbc,access,p,id(row.get("return_id")));var item=output(row);var cfg=jdbc.queryForList("select * from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and company_id=:company and enabled and workflow_version=2",base(p).addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")));boolean reviewerCurrent=!cfg.isEmpty()&&(Objects.equals(cfg.getFirst().get("finance_account_id"),row.get("reviewer_id"))||Objects.equals(cfg.getFirst().get("director_account_id"),row.get("reviewer_id")));item.put("reviewerCurrentlyConfigured",reviewerCurrent);var receipts=row.get("return_id")==null?List.<Map<String,Object>>of():jdbc.queryForList("select id,kind,external_reference,amount,occurred_on,attachment_id from fb_tax_receipt where tenant_id=:tenant and return_id=:return order by occurred_on,id",base(p).addValue("return",row.get("return_id")));BigDecimal filed=receipts.stream().filter(r->r.get("kind").equals("FILING")).map(r->amount(r.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add),paid=receipts.stream().filter(r->r.get("kind").equals("PAYMENT")).map(r->amount(r.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add);long filingCount=receipts.stream().filter(r->r.get("kind").equals("FILING")).count();String state;if(!"ACTIVE".equals(row.get("status")))state=row.get("status").toString();else if(!reviewerCurrent)state="REVIEWER_CONFIG_CHANGED";else if(row.get("return_id")==null)state="RETURN_NOT_LINKED";else if(filingCount==0)state="FILING_RECEIPT_MISSING";else if(filingCount>1||row.get("declared_amount")!=null&&filed.compareTo(amount(row.get("declared_amount")))!=0)state="FILING_AMOUNT_DIFFERENCE";else if("FILING".equals(row.get("obligation")))state="ACTUAL_FILING_ARCHIVED";else if(paid.compareTo(filed)<0)state="PAYMENT_RECEIPT_INCOMPLETE";else if(paid.compareTo(filed)>0)state="PAYMENT_AMOUNT_DIFFERENCE";else state=filed.signum()==0?"NO_PAYMENT_DUE_WITH_ACTUAL_FILING":"ACTUAL_PAYMENT_ARCHIVED";boolean complete=Set.of("ACTUAL_FILING_ARCHIVED","ACTUAL_PAYMENT_ARCHIVED","NO_PAYMENT_DUE_WITH_ACTUAL_FILING").contains(state);item.put("receiptState",state);item.put("actualFiledAmount",filed.toPlainString());item.put("actualPaidAmount",paid.toPlainString());item.put("overdue",!complete&&"ACTIVE".equals(row.get("status"))&&LocalDate.parse(row.get("due_on").toString()).isBefore(today()));item.put("receipts",receipts.stream().map(FinanceV2Support::output).toList());item.put("externalExecution","NONE");result.add(item);}return Map.of("items",result,"complete",values.size()<=200,"basis","后台按真实政策和官方日历配置义务及期限；准备取数、链接申报记录不代表已外部申报，完成状态只依据已归档真实回执");}
 public Map<String,Object> createCalendar(FinanceBusinessExceptionModels.Calendar in){var p=prepare("finance.tax");access.requirePermission("finance.configure");access.requireOrgScope(in.hotelId());lock(p,"request:"+in.requestId());var old=jdbc.queryForList("select * from fb_tax_calendar where tenant_id=:tenant and id=:id",base(p).addValue("id",in.requestId()));if(!old.isEmpty()){if(!p.actorId().equals(old.getFirst().get("created_by"))||!FinanceService.hash(json(in)).equals(old.getFirst().get("request_hash")))throw conflict("义务编号已用于其他内容");return output(old.getFirst());}var cfg=config(p,in.hotelId());independent(p,cfg,in.reviewerId());LocalDate month=month(in.month());lock(p,"calendar:"+cfg.get("company_id")+":"+in.taxKind()+":"+month+":"+in.obligation());if(jdbc.queryForObject("select count(*) from fb_tax_calendar where tenant_id=:tenant and company_id=:company and tax_kind=:kind and month=:month and obligation=:obligation and status in (\'REVIEW\',\'ACTIVE\')",base(p).addValue("company",cfg.get("company_id")).addValue("kind",in.taxKind()).addValue("month",month).addValue("obligation",in.obligation()),Integer.class)>0)throw conflict("同主体同税种所属期已有未取消义务，不能重复安排或以新期限覆盖原义务");if(in.dueOn().isBefore(month))throw bad("截止日不能早于税务所属期");var policy=jdbc.queryForList("select * from fb_tax_policy where tenant_id=:tenant and id=:id and hotel_id=:hotel and company_id=:company and published_by is not null and effective_from<=:month and effective_until>=:month",base(p).addValue("id",in.policyId()).addValue("hotel",in.hotelId()).addValue("company",cfg.get("company_id")).addValue("month",month));if(policy.size()!=1)throw conflict("须使用本主体、本所属期已独立发布的政策版本");jdbc.update("insert into fb_tax_calendar(id,tenant_id,hotel_id,company_id,policy_id,tax_kind,title,month,due_on,obligation,official_reference,request_hash,created_by,reviewer_id) values(:id,:tenant,:hotel,:company,:policy,:kind,:title,:month,:due,:obligation,:official,:hash,:actor,:reviewer)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",cfg.get("company_id")).addValue("policy",in.policyId()).addValue("kind",in.taxKind()).addValue("title",in.title()).addValue("month",month).addValue("due",in.dueOn()).addValue("obligation",in.obligation()).addValue("official",in.officialReference()).addValue("hash",FinanceService.hash(json(in))).addValue("reviewer",in.reviewerId()));notifyReview(p,"FINANCE_TAX_CALENDAR",in.requestId(),in.reviewerId());audit.record("FINANCE_TAX_OBLIGATION_REQUESTED","FINANCE_TAX_CALENDAR",in.requestId(),"{}");return output(load(p,"fb_tax_calendar",in.requestId(),false));}
 public Map<String,Object> reviewCalendar(UUID calendar,Review in){var p=prepare("finance.tax");access.requirePermission("finance.review");var row=load(p,"fb_tax_calendar",calendar,true);reviewer(p,row);version(row,in.expectedVersion());configured(config(p,id(row.get("hotel_id"))),p.actorId());if(!Set.of("REVIEW","ACTIVE").contains(row.get("status"))||in.approve()&&!"REVIEW".equals(row.get("status")))throw conflict("义务已经处理；激活后的日期/政策不可覆盖，需独立取消保留历史后建立新版");update(p,"fb_tax_calendar",calendar,in.approve()?"ACTIVE":"CANCELLED",in.note());audit.record(in.approve()?"FINANCE_TAX_OBLIGATION_ACTIVATED":"FINANCE_TAX_OBLIGATION_CANCELLED","FINANCE_TAX_CALENDAR",calendar,json(Map.of("note",in.note())));return output(load(p,"fb_tax_calendar",calendar,false));}
 public Map<String,Object> link(UUID calendar,Link in){var p=prepare("finance.tax");access.requirePermission("finance.review");var row=load(p,"fb_tax_calendar",calendar,true);reviewer(p,row);configured(config(p,id(row.get("hotel_id"))),p.actorId());version(row,in.expectedVersion());if(!"ACTIVE".equals(row.get("status")))throw conflict("须先独立确认实际税务义务");var old=jdbc.queryForList("select * from fb_tax_calendar_link where tenant_id=:tenant and calendar_id=:id",base(p).addValue("id",calendar));if(!old.isEmpty()){if(!in.requestId().equals(old.getFirst().get("id"))||!in.returnId().equals(old.getFirst().get("return_id"))||!in.note().equals(old.getFirst().get("note")))throw conflict("义务已经关联冻结申报记录，不能覆盖；需保留历史并独立取消重建义务");FinanceTaxScope.frozen(jdbc,access,p,map(old.getFirst().get("return_snapshot")));return output(old.getFirst());}var returns=jdbc.queryForList("select * from fb_tax_return where tenant_id=:tenant and id=:id and hotel_id=:hotel and company_id=:company and month=:month and policy_id=:policy",base(p).addValue("id",in.returnId()).addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")).addValue("month",row.get("month")).addValue("policy",row.get("policy_id")));if(returns.size()!=1)throw conflict("只能关联同门店同主体同所属期同政策版本的真实申报取数记录");FinanceTaxScope.frozen(jdbc,access,p,returns.getFirst());jdbc.update("insert into fb_tax_calendar_link(id,tenant_id,calendar_id,return_id,return_snapshot,actor_id,note) values(:id,:tenant,:calendar,:return,cast(:snapshot as jsonb),:actor,:note)",base(p).addValue("id",in.requestId()).addValue("calendar",calendar).addValue("return",in.returnId()).addValue("snapshot",json(output(returns.getFirst()))).addValue("note",in.note()));audit.record("FINANCE_TAX_OBLIGATION_RETURN_LINKED","FINANCE_TAX_CALENDAR",calendar,json(Map.of("returnId",in.returnId())));return output(jdbc.queryForMap("select * from fb_tax_calendar_link where tenant_id=:tenant and id=:id",base(p).addValue("id",in.requestId())));}
 private Map<String,Object> entry(TenantPrincipal p,UUID id,boolean lock){var list=jdbc.queryForList("select e.*,b.business_date,b.source,b.revision,b.version source_version,b.status batch_status from fb_revenue_entry e join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where e.tenant_id=:tenant and e.id=:id"+(lock?" for update of e":""),base(p).addValue("id",id));if(list.isEmpty())throw missing();var row=list.getFirst();access.requireOrgScope(id(row.get("hotel_id")));if(!Boolean.TRUE.equals(row.get("active"))||!"CONFIRMED".equals(row.get("batch_status"))||!Set.of("AR","INCOME").contains(row.get("kind")))throw conflict("仅当前独立确认的真实收入/应收可办理差额；押金、预收及储值不能当坏账费用");return row;}
 private BigDecimal outstanding(TenantPrincipal p,Map<String,Object> row){return jdbc.queryForObject("select :expected-coalesce(sum(case when m.kind='RECEIPT' then fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asof) when m.kind='REFUND' then -fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asof) else 0 end),0)-fb_revenue_redeemed_into(:tenant,:entry,:asof)-fb_receivable_adjusted_amount(:tenant,:entry,:asof) from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where m.tenant_id=:tenant and e.hotel_id=:hotel and e.external_id=:external and b.source=:source and b.channel=:channel and b.business_date=:business and m.occurred_on<=:asof",base(p).addValue("expected",amount(row.get("amount")).subtract(amount(row.get("commission"))).subtract(amount(row.get("fee")))).addValue("entry",row.get("id")).addValue("hotel",row.get("hotel_id")).addValue("external",row.get("external_id")).addValue("source",row.get("source")).addValue("channel",row.get("channel")).addValue("business",row.get("business_date")).addValue("asof",today()),BigDecimal.class);}
 private void validateAdjustment(TenantPrincipal p,Map<String,Object> row,BigDecimal value,LocalDate day,UUID proof){money(value);if(value.signum()<=0||value.compareTo(outstanding(p,row))>0)throw conflict("只可核销原收入尚未收款、未被消费核销、未被差额调整的净未清金额");if(day.isBefore(LocalDate.parse(row.get("business_date").toString()))||day.isAfter(today()))throw bad("调整记账日须不早于原业务日且不晚于今天");for(var book:jdbc.queryForList("select id from fa_book where tenant_id=:tenant and hotel_id=:hotel and enabled order by id",base(p).addValue("hotel",row.get("hotel_id"))))jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,0))",Map.of("key",p.tenantId()+":book:"+book.get("id")));if(jdbc.queryForObject("select count(*) from fa_period x join fa_book b on b.tenant_id=x.tenant_id and b.id=x.book_id where b.tenant_id=:tenant and b.hotel_id=:hotel and b.enabled and x.month=:month and x.status='CLOSED'",base(p).addValue("hotel",row.get("hotel_id")).addValue("month",YearMonth.from(day).atDay(1)),Integer.class)>0)throw conflict("调整记账期间已锁定，不能抹除旧期收入；请选择当前开放期");if(jdbc.queryForObject("select count(*) from fb_attachment where tenant_id=:tenant and id=:proof and hotel_id=:hotel and domain='REVENUE' and resource_id=:batch",base(p).addValue("proof",proof).addValue("hotel",row.get("hotel_id")).addValue("batch",row.get("batch_id")),Integer.class)!=1)throw conflict("请先在来源批次归档真实坏账/渠道差异依据原件，并选择对应原件编号");}
 private Map<String,Object> config(TenantPrincipal p,UUID hotel){var list=jdbc.queryForList("select * from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled and workflow_version=2",base(p).addValue("hotel",hotel));if(list.size()!=1)throw conflict("实际法人及独立财务审核配置未发布");return list.getFirst();}
 private void configured(Map<String,Object> cfg,UUID actor){if(!Objects.equals(cfg.get("finance_account_id"),actor)&&!Objects.equals(cfg.get("director_account_id"),actor))throw conflict("当前账号不是后台配置的独立财务/总监");}
 private void independent(TenantPrincipal p,Map<String,Object> cfg,UUID reviewer){configured(cfg,reviewer);if(p.actorId().equals(reviewer))throw bad("编制与独立确认须由不同账号办理");if(jdbc.queryForObject("select count(*) from user_account where tenant_id=:tenant and id=:id and status='ACTIVE'",base(p).addValue("id",reviewer),Integer.class)!=1)throw bad("指定独立审核人账号不可用");}
 private void reviewer(TenantPrincipal p,Map<String,Object> row){if(!p.actorId().equals(row.get("reviewer_id"))||p.actorId().equals(row.get("created_by")))throw conflict("当前账号不是本笔冻结的独立审核人");}
 private void sourceVersion(Map<String,Object> row,int expected){if(((Number)row.get("source_version")).intValue()!=expected)throw conflict("来源修订版本已变化，请刷新后重新核对");}
 private void update(TenantPrincipal p,String table,UUID id,String status,String note){jdbc.update("update "+table+" set status=:status,reviewed_by=:actor,review_note=:note,reviewed_at=now(),version=version+1 where tenant_id=:tenant and id=:id",base(p).addValue("id",id).addValue("status",status).addValue("note",note));}
 private Map<String,Object> load(TenantPrincipal p,String table,UUID id,boolean lock){if(!Set.of("fb_receivable_adjustment","fb_receivable_recovery","fb_tax_calendar").contains(table))throw new IllegalArgumentException();var list=jdbc.queryForList("select * from "+table+" where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(list.isEmpty())throw missing();access.requireOrgScope(id(list.getFirst().get("hotel_id")));return list.getFirst();}
 private String hash(Map<String,Object> row){return FinanceService.hash(json(output(row)));}
 private void lock(TenantPrincipal p,String key){jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,101))",Map.of("key",p.tenantId()+":"+key));}
 private static String scope(String alias){return "(:tenantScope or "+alias+".hotel_id in (:scopes))";}
 private void notifyReview(TenantPrincipal p,String type,UUID source,UUID recipient){jdbc.update("insert into notification(tenant_id,recipient_account_id,notification_type,title,content,source_type,source_id,idempotency_key) values(:tenant,:recipient,\'FINANCE_REVIEW_PENDING\',\'财务业务待独立核对\',\'有一笔财务业务等待独立核对原件、冻结来源及当前配置。消息不含敏感明细；以实时身份和权限节点为准。\',:type,:source,:key) on conflict(tenant_id,recipient_account_id,idempotency_key) do nothing",base(p).addValue("recipient",recipient).addValue("type",type).addValue("source",source).addValue("key",type+":"+source+":REVIEW:0:"+recipient));}
 private TenantPrincipal prepare(String... permissions){access.requireAnyPermission(permissions);var p=access.principal();db.apply(p.tenantId());return p;}
 private static LocalDate today(){return LocalDate.now(ZoneId.of("Asia/Shanghai"));}
 private static BigDecimal money(BigDecimal n){try{var d=n.setScale(2,RoundingMode.UNNECESSARY);if(d.precision()>18)throw new ArithmeticException();return d;}catch(Exception e){throw bad("金额须为精确分值，不接受隐式四舍五入");}}
}
